    setWidth(width) {
        if (width !== 'auto') {
            setStyleAttribute(this.element, { 'width': formatUnit(this.width) });
        }
        else {
            this.element.style.width = 'auto';
        }
    }
    setCssClass(cssClass) {
        if (!isNullOrUndefined(cssClass)) {
            const allClassName = cssClass.split(' ');
            for (let i = 0; i < allClassName.length; i++) {
                if (allClassName[i].trim() !== '') {
                    this.element.classList.add(allClassName[i]);
                }
            }
        }
    }
    updateRTL() {
        this.notify(rtlMode, { enableRtl: this.enableRtl });
        if (this.enableRtl) {
            this.element.classList.add(CLS_RTL);
            this.inputElement.classList.add(CLS_RTL);
        }
        else {
            this.element.classList.remove(CLS_RTL);
            this.inputElement.classList.remove(CLS_RTL);
        }
    }
    updateReadOnly() {
        this.notify(readOnlyMode, { editPanel: this.inputElement, mode: this.readonly });
    }
    /**
     * setReadOnly method
     *
     * @param {boolean} initial - specifies the boolean value
     * @returns {void}
     * @hidden
     * @deprecated
     */
    setReadOnly(initial) {
        this.updateReadOnly();
        if (!initial) {
            if (this.readonly && this.enabled) {
                this.unbindEvents();
                this.unWireEvents();
            }
            else if (this.enabled) {
                this.wireEvents();
            }
        }
    }
    /**
     * Prints all the pages of the RichTextEditor by default.
     *
     * @returns {void}
     */
    print() {
        let printWind;
        const printArgs = {
            element: this.inputElement,
            requestType: 'print',
            cancel: false
        };
        this.trigger(actionBegin, printArgs, (printingArgs) => {
            printWind = window.open('', 'print', 'height=' + window.outerHeight + ',width=' + window.outerWidth);
            if (Browser.info.name === 'msie') {
                printWind.resizeTo(screen.availWidth, screen.availHeight);
            }
            if (this.iframeSettings.enable) {
                printWind = openPrintWindow(this.inputElement, printWind);
            }
            else {
                const wrapper = document.createElement('div');
                addClass([wrapper], ['e-richtexteditor', 'e-control']);
                const content = document.createElement('div');
                addClass([content], ['e-rte-content']);
                content.appendChild(this.inputElement.cloneNode(true));
                wrapper.appendChild(content);
                printWind = print(wrapper, printWind);
            }
            if (!printingArgs.cancel) {
                const actionArgs = {
                    requestType: 'print'
                };
                this.trigger(actionComplete, actionArgs);
            }
        });
    }
